head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > maskFormatModelExcludeCharValue]<br/>getValue() 메소드로 입력값을 반환받을때 maskFormatModelExcludeChar 속성을 적용할지 여부를 설정합니다.",
    "validation" : [
        "maskFormat 속성값이 'none' 이 아니고, maskFormatModelExcludeChar 속성이 설정된 경우 동작합니다",
        "미설정 시 입력값을 그대로 반환합니다. ",
        "true 설정 시 입력값에서 maskFormatModelExcludeChar 속성의 문자를 모두 제거한 값을 반환합니다.",
        "false 설정 시 입력값을 그대로 반환합니다. ",        
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.getValue = function(target) {    
    let rtn = '';
    rtn = target.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue("getValue : " + rtn);    
}



scwin.getBindData = function(target) {
    let rtn = '';
    rtn = dm_ref.get("key1");

    wf_body_bottom.getObj("scwin").setReturnValue("bind value : " + rtn);    
}



 // 사용자 정의 함수
 scwin.fn_dpformatter = function(val) {
    return "language -> " + val;
 };



// target1
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("(031)123-4567");
};

scwin.btn_getValue1_onclick = function (e) {
    scwin.getValue(target1);
};

